const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const command=async(a,p)=>{try{return await window.veyra.command(a,p)}catch(e){toast(String(e.message).replace(/^Error invoking remote method '[^']+': (?:Error: )?/,''));return undefined}};
let offlineGame=null,lastFocusedHome=null,customizeMode=false;
let state=null,contentKey='',panelKey='',toastTimer,vaultEntries=[],cardEntries=[],bookmarkEditing=null,collectionQuery='',folderFilter='';
const current=()=>state?.tabs.find(t=>t.id===state.selected);
const language=()=>state?.settings?.language||'ru';
const tr=text=>window.VeyraI18n.translate(text,language());
const modeName=t=>tr(t?.mode==='local'?'Локальный файл':t?.compatibility?'Совместимость сайта':t?.mode==='temporary'?'Временный профиль':'Защита сайта');
const supportServerButton=()=>`<button type="button" class="support-server" data-action="support-server" title="${esc(tr('Сервер поддержки в Discord'))}" aria-label="${esc(tr('Сервер поддержки в Discord'))}">${icon('discord')}</button>`;
const logo=(size=48)=>`<svg class="brand-image" role="img" aria-label="Veyra" width="${size}" height="${size}" viewBox="0 0 64 64" fill="none"><path d="M32 5 55.4 18.5v27L32 59 8.6 45.5v-27L32 5Z" fill="var(--accent)"/><path d="m16 28 16-9 16 9-16 9-16-9Z" fill="var(--surface)"/><path d="m16 36 16 9 16-9" stroke="var(--surface)" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><path d="m32 19 16 9-16 9" stroke="var(--text)" stroke-opacity=".55" stroke-width="2" stroke-linejoin="round"/></svg>`;
const safeOrigin=url=>{try{return new URL(url).origin}catch{return ''}};
const webURL=url=>/^https?:\/\//.test(url||'');
function toast(message){$('#toast').textContent=tr(String(message));$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
for(const b of document.querySelectorAll('[data-icon]'))b.innerHTML=icon(b.dataset.icon);
for(const id of ['minimize','maximize','close','back','forward','bookmark'])$('#'+id).onclick=()=>command(id);
$('#brand').onclick=$('#new').onclick=()=>command('new');$('#reload').onclick=()=>command(current()?.loading?'stop':'reload');
for(const name of ['privacy','downloads','menu'])$('#'+name).onclick=()=>{if(name==='downloads')acknowledgeDownloads();return command('panel',name)};
for(const b of document.querySelectorAll('[data-rail]'))b.onclick=()=>command('panel',b.dataset.rail);
$('#temporary').onclick=()=>command('temporary');$('#open-settings').onclick=()=>command('navigate','veyra://settings');
$('#address-form').onsubmit=e=>{e.preventDefault();const value=$('#address').value;hideAddressSuggestions();command('navigate',value);$('#address').blur()};$('#address').onfocus=()=>{$('#address').select();showAddressSuggestions()};$('#address').addEventListener('input',showAddressSuggestions);document.addEventListener('mousedown',e=>{if(!e.target.closest('#address-wrap'))hideAddressSuggestions();if(!e.target.closest('.home-search-wrap'))hideSuggestionBox($('#home-suggestions'));if(!e.target.closest('.home-engine'))closeHomeEngineMenu()});window.veyra.onAddress(()=>{$('#address').focus();$('#address').select()});window.veyra.onToast(toast);
let addressSuggestionIndex=-1;
let homeSuggestionIndex=-1;
function hideAddressSuggestions(){const el=$('#address-suggestions');if(el)el.hidden=true;addressSuggestionIndex=-1}
function paintAddressSuggestion(rows){rows.forEach((row,i)=>row.classList.toggle('active',i===addressSuggestionIndex));rows[addressSuggestionIndex]?.scrollIntoView({block:'nearest'})}
function suggestionRows(query){const q=query.trim().toLowerCase(),history=(state.history||[]).filter(x=>x.url&&(!q||x.title?.toLowerCase().includes(q)||x.url.toLowerCase().includes(q))),searches=(state.recentSearches||[]).filter(x=>!q||x.query.toLowerCase().includes(q)),seen=new Set(),rows=[];for(const item of [...history,...searches]){const text=item.query||item.title||item.url,key=text.toLowerCase();if(!text||seen.has(key))continue;seen.add(key);rows.push({text,url:item.url||'',meta:item.url?new URL(item.url).hostname:tr('Recent search'),icon:item.url?'◉':'◷'})}if(q&&!/^https?:\/\//i.test(q)){const engine=state.settings.search==='google'?'Google':'DuckDuckGo';rows.unshift({text:`${query.trim()} · ${tr('Search with')} ${engine}`,url:'',meta:engine,icon:'⌕',search:true})}return rows.slice(0,8)}
function paintSuggestions(input,box,rows,select){box.innerHTML=rows.map((x,i)=>`<button type="button" role="option" class="suggestion" data-address-suggestion="${i}" data-suggest-url="${esc(x.url)}" data-suggest-query="${esc(x.search?input.value.trim():x.url||x.text)}"><span class="suggestion-icon">${esc(x.icon)}</span><span class="suggestion-main">${esc(x.text)}</span><span class="suggestion-meta">${esc(x.meta)}</span></button>`).join('');box.hidden=!rows.length;addressSuggestionIndex=-1;const items=[...box.querySelectorAll('[data-address-suggestion]')];input.onkeydown=e=>{if(e.key==='ArrowDown'&&items.length){e.preventDefault();addressSuggestionIndex=(addressSuggestionIndex+1)%items.length;paintAddressSuggestion(items)}else if(e.key==='ArrowUp'&&items.length){e.preventDefault();addressSuggestionIndex=(addressSuggestionIndex-1+items.length)%items.length;paintAddressSuggestion(items)}else if(e.key==='Escape')hideSuggestionBox(box);else if(e.key==='Enter'&&addressSuggestionIndex>=0&&items[addressSuggestionIndex]){e.preventDefault();select(items[addressSuggestionIndex])}};items.forEach(button=>{button.onmousedown=e=>e.preventDefault();button.onclick=()=>select(button)})}
function hideSuggestionBox(box){if(box)box.hidden=true;addressSuggestionIndex=-1}
function showAddressSuggestions(){const input=$('#address'),box=$('#address-suggestions');if(!input||!box||document.activeElement!==input)return;paintSuggestions(input,box,suggestionRows(input.value),button=>{const destination=button.dataset.suggestUrl||button.dataset.suggestQuery;hideSuggestionBox(box);command('navigate',destination);input.blur()})}
function homeRows(query){const q=query.trim().toLowerCase(),history=(state.history||[]).filter(x=>x.url&&(!q||x.title?.toLowerCase().includes(q)||x.url.toLowerCase().includes(q))),searches=(state.recentSearches||[]).filter(x=>!q||x.query.toLowerCase().includes(q)),rows=[],seen=new Set();for(const item of history.slice(0,6)){let host='';try{host=new URL(item.url).hostname}catch{}const key=item.url;if(seen.has(key))continue;seen.add(key);const tab=state.tabs.find(t=>{try{return new URL(t.url).origin===new URL(item.url).origin&&t.favicon?.startsWith('data:image/')}catch{return false}});rows.push({kind:'site',text:item.title||host,url:item.url,meta:host,favicon:item.favicon||tab?.favicon||'',icon:'globe'})}if(searches.length){rows.push({kind:'label',text:tr('Recent searches')});for(const item of searches.slice(0,5)){if(seen.has('search:'+item.query))continue;seen.add('search:'+item.query);rows.push({kind:'search-history',text:item.query,meta:tr('Recent search'),icon:'history',query:item.query})}}if(q&&!/^https?:\/\//i.test(query.trim()))rows.push({kind:'search',text:`${tr('Search with')} ${state.settings.search==='google'?'Google':'DuckDuckGo'}: ${query.trim()}`,meta:state.settings.search==='google'?'Google':'DuckDuckGo',icon:'search',query:query.trim()});return rows}
function paintHomeSuggestions(input,box,rows){const options=[];box.innerHTML=rows.map(row=>{if(row.kind==='label')return `<div class="home-suggestion-label">${esc(row.text)}</div>`;const i=options.push(row)-1,iconHtml=row.favicon?`<img src="${esc(row.favicon)}" alt="" loading="lazy">`:icon(row.icon||'globe');return `<button type="button" role="option" class="home-suggestion" data-home-suggestion="${i}" data-url="${esc(row.url||'')}" data-query="${esc(row.query||'')}"><span class="home-suggestion-icon">${iconHtml}</span><span class="home-suggestion-title">${esc(row.text)}</span>${row.meta?`<span class="home-suggestion-separator">·</span><span class="home-suggestion-meta">${esc(row.meta)}</span>`:''}</button>`}).join('');box.hidden=!options.length;homeSuggestionIndex=-1;const items=[...box.querySelectorAll('[data-home-suggestion]')];input.onkeydown=e=>{if(e.key==='ArrowDown'&&items.length){e.preventDefault();homeSuggestionIndex=(homeSuggestionIndex+1)%items.length;paintHomeActive(box,items)}else if(e.key==='ArrowUp'&&items.length){e.preventDefault();homeSuggestionIndex=(homeSuggestionIndex-1+items.length)%items.length;paintHomeActive(box,items)}else if(e.key==='Escape'){hideSuggestionBox(box);homeSuggestionIndex=-1}else if(e.key==='Enter'&&homeSuggestionIndex>=0&&items[homeSuggestionIndex]){e.preventDefault();items[homeSuggestionIndex].click()}};items.forEach(button=>button.onclick=()=>{hideSuggestionBox(box);const url=button.dataset.url,queryValue=button.dataset.query;if(url)command('navigate',url);else command('search',queryValue||button.querySelector('.home-suggestion-title')?.textContent.replace(/^.*?:\s*/,'')||'');input.blur()})}
function paintHomeActive(box,items){items.forEach((row,i)=>row.classList.toggle('active',i===homeSuggestionIndex));items[homeSuggestionIndex]?.scrollIntoView({block:'nearest'})}
function closeHomeEngineMenu(){const menu=$('#home-engine-menu'),button=$('#home-engine-toggle');if(menu)menu.hidden=true;if(button)button.setAttribute('aria-expanded','false')}
function home(){const t=current(),engine=state.settings.search==='google'?'google':'duckduckgo';return `<div class="home animate-in"><div class="home-top"><span>${esc(new Intl.DateTimeFormat(language(),{weekday:'long',day:'numeric',month:'long'}).format(new Date()))}</span></div><div class="home-center"><div class="wordmark">${logo(68)}<h1>veyra</h1></div><div class="home-search-wrap"><form class="search-form" id="home-search"><div class="home-engine"><button type="button" id="home-engine-toggle" aria-label="${esc(tr('Search engine'))}" aria-expanded="false"><span class="engine-mark ${engine}" aria-hidden="true">${engine==='google'?'G':'D'}</span><span class="engine-chevron" aria-hidden="true">⌄</span></button><div id="home-engine-menu" class="home-engine-menu" role="menu" hidden><button type="button" role="menuitemradio" data-engine="google" aria-checked="${engine==='google'}"><span class="engine-mark google">G</span>Google${engine==='google'?icon('check'):''}</button><button type="button" role="menuitemradio" data-engine="duckduckgo" aria-checked="${engine==='duckduckgo'}"><span class="engine-mark duckduckgo">D</span>DuckDuckGo${engine==='duckduckgo'?icon('check'):''}</button></div></div><input id="home-query" placeholder="${esc(tr('Search or enter address'))}" autocomplete="off" aria-label="${esc(tr('Search or enter address'))}"><button aria-label="${esc(tr('Search'))}">${icon('arrow')}</button></form><div id="home-suggestions" class="home-suggestions" role="listbox" hidden></div></div>${state.settings.shortcuts.length?`<div class="shortcuts">${state.settings.shortcuts.map(x=>`<button class="shortcut" data-url="${esc(x.url)}"><span class="tile">${(x.image||x.favicon)?.startsWith('data:image/')?`<img src="${esc(x.image||x.favicon)}" alt="" loading="lazy">`:icon('globe')}</span><span class="user-shortcut-title">${esc(x.title)}</span></button>`).join('')}</div>`:''}${t.mode==='temporary'?`<p class="note">${esc(tr('Shared temporary profile: no history or password saving. Data is removed when Veyra fully closes.'))}</p>`:''}</div>${widgetHome()}<div class="home-bottom"><button data-action="customize-mode">${customizeMode?esc(tr('Готово')):esc(tr('Настроить'))} ${icon('chevron')}</button></div></div>`}
function toggle(k,title,note){return `<label class="setting"><div><strong>${title}</strong><p>${note}</p></div><input class="toggle" type="checkbox" name="${k}" ${state.settings[k]?'checked':''}></label>`}
function performanceForm(){const s=state.settings;return `<form id="performance-form"><div class="network-limits"><label class="field">${esc(tr('Загрузка, Мбит/с'))}<input type="number" name="networkDownMbps" min="0" max="1000" step="0.1" value="${s.networkDownMbps||0}"></label><label class="field">${esc(tr('Отправка, Мбит/с'))}<input type="number" name="networkUpMbps" min="0" max="1000" step="0.1" value="${s.networkUpMbps||0}"></label></div><p class="note">${esc(tr('Лимит скорости каждой вкладки. 0 — без ограничения. В профиле Google не применяется.'))}</p><label class="field">${esc(tr('Мягкая цель RAM'))} <span class="range-value" id="ram-value">${s.ramTargetMB} ${esc(tr('МБ'))}</span><input type="range" name="ramTargetMB" min="512" max="8192" step="256" value="${s.ramTargetMB}"></label><p class="note">${esc(tr('Браузер усыпляет фоновые вкладки, чтобы снизить расход памяти. Значение может быть превышено.'))}</p><label class="field">${esc(tr('Перезапускать при высоком расходе памяти'))}<input type="checkbox" class="toggle" name="autoRestartHighMemory" ${s.autoRestartHighMemory?'checked':''}></label><p class="note">${esc(tr('Срабатывает после 15 секунд выше порога; сначала открытые сайты сохраняются как спящие вкладки. Не срабатывает при загрузках, звуке или несохранённых полях.'))}</p><label class="field">${esc(tr('Порог перезапуска, МБ'))}<input type="number" name="highMemoryLimitMB" min="2048" max="32768" step="256" value="${s.highMemoryLimitMB||6144}"></label><label class="field">${esc(tr('Живых фоновых вкладок'))}<input type="number" name="maxBackgroundTabs" min="1" max="30" value="${s.maxBackgroundTabs}"></label><label class="field">${esc(tr('Усыплять после, минут'))}<input type="number" name="sleepMinutes" min="1" max="120" value="${s.sleepMinutes}"></label>${toggle('eco',esc(tr('Режим экономии')),esc(tr('Усыплять подходящие фоновые вкладки по времени и потреблению памяти.')))}${toggle('hardwareAcceleration',esc(tr('Аппаратное ускорение')),esc(tr('Использовать GPU для отрисовки. Изменение требует перезапуска.')))}<button class="primary wide" type="submit">${esc(tr('Сохранить'))}</button></form>`}
function settings(){return `<div class="page animate-in"><h1>Настройки</h1><nav class="settings-categories" aria-label="Категории настроек"><button type="button" class="settings-category active" data-settings-jump="settings-appearance">${esc(tr("Appearance & search"))}</button><button type="button" class="settings-category" data-settings-jump="settings-tabs">${esc(tr("Tabs"))}</button><button type="button" class="settings-category" data-settings-jump="settings-privacy">${esc(tr("Privacy"))}</button><button type="button" class="settings-category" data-settings-jump="settings-profiles">${esc(tr("Profiles"))}</button><button type="button" class="settings-category" data-settings-jump="settings-performance">${esc(tr("Performance"))}</button><button type="button" class="settings-category" data-settings-jump="settings-data">${esc(tr("Data & permissions"))}</button><button type="button" class="settings-category" data-settings-jump="settings-file-types">${esc(tr("File types"))}</button></nav><form id="settings-form"><div class="section" id="settings-appearance">ОФОРМЛЕНИЕ И ПОИСК</div><div class="card"><div class="setting"><div><strong>Язык интерфейса</strong><p>Интерфейс меняется сразу. Язык расширений — после перезапуска.</p></div><select name="language" id="language-select" aria-label="Язык интерфейса">${[['ru','Русский'],['uk','Українська'],['en','English'],['de','Deutsch'],['fr','Français'],['es','Español'],['pl','Polski']].map(([v,l])=>`<option value="${v}" ${language()===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="setting"><strong>Оформление</strong><select name="theme">${[['dark','Тёмное'],['light','Светлое'],['system','Системное']].map(([v,l])=>`<option value="${v}" ${state.settings.theme===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="setting"><strong>Поиск</strong><select name="search">${[['duckduckgo','DuckDuckGo'],['google','Google']].map(([v,l])=>`<option value="${v}" ${state.settings.search===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="card"><div class="setting"><div><strong>Темы и обои</strong><p>Цвета, фон новой вкладки и своё изображение.</p></div><button class="secondary" type="button" data-panel="customize">Настроить</button></div></div><div class="settings-actions"><button class="settings-action" type="button" data-url="veyra://compatibility">${icon('shield')}<span>Список совместимости</span>${icon('chevron')}</button><button class="settings-action" type="button" data-panel="dark">${icon('moon')}<span>Auto Dark Mode</span>${icon('chevron')}</button><button class="settings-action" type="button" data-url="veyra://discord">${icon('globe')}<span>Discord Rich Presence</span>${icon('chevron')}</button></div><div class="card inset"><button class="secondary" type="button" data-action="default-browser">Сделать браузером по умолчанию</button></div><div class="section" id="settings-tabs">ВКЛАДКИ</div><div class="card">${toggle('popupWindows','Открывать сайты отдельными окнами','Обычные ссылки открываются вкладками. Явные всплывающие окна сайтов сохраняются.')}${toggle('bookmarksBar','Панель закладок','Показывать закладки под адресной строкой.')}${toggle('restoreSession','Восстанавливать вкладки при запуске','Сохраняются адреса страниц. Введённые данные и временные вкладки не сохраняются.')}</div><div class="card"><div class="setting"><div><strong>Копирование с сайтов</strong><p>Чтение буфера требует отдельного разрешения.</p></div><select name="clipboardMode"><option value="auto" ${state.settings.clipboardMode==='auto'?'selected':''}>Копировать сразу</option><option value="ask" ${state.settings.clipboardMode==='ask'?'selected':''}>Спрашивать с предпросмотром</option></select></div></div><div class="section" id="settings-privacy">ПРИВАТНОСТЬ</div><div class="card">${toggle('trackers','Блокировка рекламы и трекеров','Использовать списки EasyList и EasyPrivacy.')}${toggle('thirdPartyCookies','Блокировать сторонние cookie','Ограничивать отправку и установку cookie сторонними ресурсами. Некоторые формы требуют исключения.')}${toggle('httpsFirst','Предпочитать HTTPS','Возврат к HTTP доступен вручную при ошибке.')}${toggle('webrtc','Ограничить прямые UDP-соединения WebRTC','Снижает риск обхода прокси. Может влиять на звонки. IP обычного соединения не скрывает.')}${toggle('dnt','Сигналы отказа от отслеживания','Заголовки DNT и Sec-GPC. Это запрос к сайту, а не принудительная блокировка.')}${toggle('autoUpdateFilters','Обновлять списки блокировки','При запуске, если списки старше суток. Запросы идут к источникам списков uBlock Origin.')}</div><button class="primary" type="submit">Сохранить настройки</button></form><div class="settings-actions"><button class="settings-action" data-url="veyra://widgets">${icon("plus")}<span>Виджеты</span>${icon("chevron")}</button><button class="settings-action" data-url="veyra://sidebar">${icon("settings")}<span>Боковая панель</span>${icon("chevron")}</button></div><div class="settings-actions profile-link"><button class="settings-action" type="button" data-url="veyra://sync">${icon("globe")}<span>Профиль и синхронизация</span>${icon("chevron")}</button></div><div class="card inset"><strong>Обновления</strong><p class="note">Проверка подписи и контрольной суммы. Установка вручную.</p><button class="secondary" type="button" id="check-updates">Проверить обновления</button><p id="update-result" role="status"></p><button class="primary" type="button" id="download-update" hidden>Скачать проверенную сборку</button></div><div class="section" id="settings-profiles">ПРОФИЛИ</div><div class="card"><div class="setting"><div><strong>Сервисы Google</strong><p>Открывать Google в полноценном браузере.</p></div><button class="secondary" data-action="google-mode">Открыть</button></div><div class="setting"><div><strong>Временный профиль</strong><p>Хранилища в памяти, без истории и сохранения паролей.</p></div><button class="secondary" data-action="temporary">Открыть</button></div></div><div class="section" id="settings-performance">ПРОИЗВОДИТЕЛЬНОСТЬ</div><div class="card inset">${performanceForm()}</div><div class="section" id="settings-data">ДАННЫЕ И РАЗРЕШЕНИЯ</div>${externalApplicationsSettings()}<div class="section" id="settings-file-types">${esc(tr('File types'))}</div><div class="card"><p class="note">${esc(tr('Choose which local file types appear in Open file. Each selected file opens in its own tab.'))}</p><div class="file-type-options">${[['html','HTML pages'],['htm','HTM pages'],['xhtml','XHTML pages'],['xht','XHT pages'],['shtml','Server-side HTML pages'],['xml','XML documents'],['svg','SVG images'],['txt','Text files'],['json','JSON files'],['pdf','PDF documents'],['png','PNG images'],['jpg','JPEG images'],['jpeg','JPEG images'],['webp','WebP images'],['avif','AVIF images'],['bmp','Bitmap images'],['gif','GIF images'],['ico','Icon files'],['css','CSS files'],['js','JavaScript files'],['mjs','JavaScript modules'],['csv','CSV files'],['md','Markdown files']].map(([ext,title])=>`<label class="file-type-option"><input type="checkbox" name="openFileTypes" value="${ext}" ${(state.settings.openFileTypes||['html','htm','xhtml','svg','xml','txt','json','pdf','png','jpg','jpeg','gif','webp','avif','bmp','ico','css','js','mjs','csv','md']).includes(ext)?'checked':''}><span><strong>.${ext}</strong><small>${esc(tr(title))}</small></span></label>`).join('')}</div></div><div class="card"><div class="setting"><div><strong>${esc(tr('Choose file associations in Windows'))}</strong><p>${esc(tr('Veyra can appear for supported extensions in Windows Default apps. Windows applies your choice there.'))}</p></div><button class="secondary" type="button" data-action="default-filetypes">${esc(tr('Open Windows file type settings'))}</button></div></div><div class="card"><div class="setting"><div><strong>Общий профиль Veyra</strong><p>Входы на сайты и настройки сохраняются между версиями на этом ПК.</p></div><button class="secondary" data-action="open-profile">Открыть папку</button></div></div><div class="card"><div class="setting"><div><strong>История</strong><p>Локальная история посещений.</p></div><button class="secondary" data-confirm="clear-history">Очистить</button></div><div class="setting"><div><strong>Cookie, кэш и хранилища</strong><p>Выход из аккаунтов. Менеджер паролей сохраняется.</p></div><button class="secondary" data-confirm="clear-data">Очистить</button></div><div class="setting"><div><strong>Разрешения сайтов</strong><p>Сбросить доступ к камере, микрофону и другим функциям.</p></div><button class="secondary" data-action="permissions-reset">Сбросить</button></div></div><details class="technical-info"><summary>О браузере</summary><div class="version-line"><p class="note">Veyra ${esc(state.version)} by Nexaridev · Windows</p>${supportServerButton()}</div><p class="note">Защита от отпечатка устройства ограничена. IP-адрес не скрывается. Автообновление приложения не настроено.</p></details></div>`}
